INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM203AIZR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a town, the population increased by $14\\%$ from 2018 to 2020, reaching $23{,}370$ residents. Which of the following is closest to the population of the town in 2018?', NULL, $lyceon_json$[{"key":"A","text":"$20{,}100$"},{"key":"B","text":"$20{,}500$"},{"key":"C","text":"$20{,}898$"},{"key":"D","text":"$26{,}642$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $P$ be the 2018 population. After a $14\\%$ increase, the population is $1.14P = 23{,}370$. Solving gives $P = \\frac{23{,}370}{1.14} \\approx 20{,}500$. The distractor $20{,}100$ results from an arithmetic rounding error in the division. The distractor $20{,}898$ comes from subtracting $14\\%$ of $23{,}370$ from $23{,}370$ (applying the percentage to the final value rather than dividing by $1.14$): $0.14 \\times 23{,}370 = 3{,}271.8$, yielding approximately $20{,}098$, which is then misrecorded as $20{,}898$ through a digit transposition. The distractor $26{,}642$ results from adding $14\\%$ of $23{,}370$ to $23{,}370$, treating the known value as the base for a further increase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM206HJN6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'A parabola is defined by $y = f(x)$ where $f(x) = a(x - 3)^2 - 7$ for some positive constant $a$. The function $g(x) = f(x - 11) + 4$ is also a parabola. What is the vertex of $g$?', NULL, $lyceon_json$[{"key":"A","text":"$(14, -3)$"},{"key":"B","text":"$(-8, -3)$"},{"key":"C","text":"$(14, -11)$"},{"key":"D","text":"$(-8, -11)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vertex of $f$ is at $(3, -7)$. Replacing $x$ with $x - 11$ shifts the parabola $11$ units to the right, moving the $x$-coordinate from $3$ to $3 + 11 = 14$. Adding $4$ shifts the parabola up $4$ units, moving the $y$-coordinate from $-7$ to $-7 + 4 = -3$. The new vertex is $(14, -3)$. The vertex $(-8, -3)$ incorrectly subtracts $11$ from the $x$-coordinate instead of adding it. The vertex $(14, -11)$ correctly shifts right but subtracts $4$ instead of adding. The vertex $(-8, -11)$ applies both shifts in the wrong direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM209YKWU', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $h$ is defined by $h(x) = \\frac{4x + 13}{3}$. For what value of $x$ does $h(x) = 19$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Setting $h(x) = 19$: $\\frac{4x + 13}{3} = 19$. Multiplying both sides by 3 gives $4x + 13 = 57$. Subtracting 13 from both sides gives $4x = 44$. Dividing by 4: $x = 11$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20BPTT3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $4(3x + 7) = 11x + 51$?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$\\frac{51}{11}$"},{"key":"C","text":"$79$"},{"key":"D","text":"$-23$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing on the left side gives $12x + 28 = 11x + 51$. Subtracting $11x$ from both sides yields $x + 28 = 51$. Subtracting 28 from both sides gives $x = 23$. The value $\\frac{51}{11}$ comes from ignoring the distributed left side entirely and solving $11x = 51$. The value $79$ comes from incorrectly adding $28 + 51$ instead of subtracting. The value $-23$ results from a sign error when moving terms across the equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21L44LX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = x^2 - 3x + 11$. What is the value of $g(-2)$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$15$"},{"key":"C","text":"$21$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = -2$: $g(-2) = (-2)^2 - 3(-2) + 11 = 4 + 6 + 11 = 21$. The value $9$ results from incorrectly computing $-3(-2)$ as $-6$ instead of $+6$, giving $4 - 6 + 11 = 9$. The value $15$ comes from forgetting to square and using $-2$ directly: $-2 + 6 + 11 = 15$. The value $1$ results from an arithmetic error when combining the terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM223A82P', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'What is the greatest integer value of $x$ that satisfies the inequality $-5x + 13 \\geq 2x - 8$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Subtracting $2x$ from both sides gives $-7x + 13 \\geq -8$. Subtracting $13$ from both sides gives $-7x \\geq -21$. Dividing both sides by $-7$ and reversing the inequality yields $x \\leq 3$. The greatest integer satisfying $x \\leq 3$ is $3$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2256DX5', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A bookstore charges a flat shipping fee of $\\$4$ plus $\\$3$ per book. A customer has at most $\\$31$ to spend on shipping. Which inequality represents the number of books $b$ the customer can order?', NULL, $lyceon_json$[{"key":"A","text":"$3b + 4 \\leq 31$"},{"key":"B","text":"$4b + 3 \\leq 31$"},{"key":"C","text":"$3b + 4 \\geq 31$"},{"key":"D","text":"$3b - 4 \\leq 31$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total shipping cost is $3$ dollars per book plus a $4$ dollar flat fee, giving $3b + 4$. Since the customer has at most $31$ dollars, the total must be less than or equal to $31$, so $3b + 4 \\leq 31$. The choice $4b + 3 \\leq 31$ swaps the per-book rate and the flat fee. The choice $3b + 4 \\geq 31$ reverses the inequality direction, representing a minimum rather than a maximum. The choice $3b - 4 \\leq 31$ subtracts the flat fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM242SX3B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A jar contains $9$ red marbles, $6$ blue marbles, and $5$ green marbles. Two marbles are drawn at random without replacement. What is the probability that both marbles are blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{12}$"},{"key":"B","text":"$\\frac{3}{38}$"},{"key":"C","text":"$\\frac{9}{100}$"},{"key":"D","text":"$\\frac{1}{19}$"}]$lyceon_json$::jsonb, 'B', NULL, E'There are $9 + 6 + 5 = 20$ marbles total. The probability that the first marble is blue is $\\frac{6}{20}$. Given the first is blue, there are $5$ blue marbles remaining out of $19$ total, so the probability the second is also blue is $\\frac{5}{19}$. The combined probability is $\\frac{6}{20} \\times \\frac{5}{19} = \\frac{30}{380} = \\frac{3}{38}$. The distractor $\\frac{1}{12}$ results from an arithmetic simplification error. The distractor $\\frac{9}{100}$ comes from computing $\\frac{6}{20} \\times \\frac{6}{20} = \\frac{36}{400} = \\frac{9}{100}$, incorrectly treating the draws as with replacement. The distractor $\\frac{1}{19}$ results from an off-by-one error on the blue marble count, using $5$ instead of $6$: $\\frac{\\binom{5}{2}}{\\binom{20}{2}} = \\frac{10}{190} = \\frac{1}{19}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM259T2RK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the value of $x$ that satisfies the equation $\\frac{5x + 11}{x - 1} = 7$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Multiplying both sides by $(x - 1)$ gives $5x + 11 = 7(x - 1) = 7x - 7$. Rearranging: $11 + 7 = 7x - 5x$, so $18 = 2x$, yielding $x = 9$. Checking: $\\frac{5(9) + 11}{9 - 1} = \\frac{56}{8} = 7$, which confirms the solution. The value $x = 9$ is valid since $9 \\neq 1$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25ENP1Q', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $p(x) = 4(x + 3)^2 - 19$ has a minimum value at $x = a$. What is the value of $p(a)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-19', ARRAY['-19'], E'The function $p(x) = 4(x + 3)^2 - 19$ is in vertex form. Since the coefficient $4$ is positive, the parabola opens upward and has a minimum at the vertex. The vertex occurs at $x = -3$, and the minimum output value is $p(-3) = 4(0)^2 - 19 = -19$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM261TM6O', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A painter charges $\\$19$ per hour and a helper charges $\\$11$ per hour. The painter works $p$ hours and the helper works $h$ hours. The total labor cost must be at most $\\$450$, the painter must work at least $6$ hours, and the helper must work at least $3$ hours. Which system of inequalities represents all the constraints?', NULL, $lyceon_json$[{"key":"A","text":"$19p + 11h \\leq 450$, $p \\geq 6$, $h \\geq 3$"},{"key":"B","text":"$19p + 11h \\geq 450$, $p \\geq 6$, $h \\geq 3$"},{"key":"C","text":"$11p + 19h \\leq 450$, $p \\geq 6$, $h \\geq 3$"},{"key":"D","text":"$19p + 11h \\leq 450$, $p \\leq 6$, $h \\leq 3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The painter earns $19$ per hour and the helper earns $11$ per hour, so total cost is $19p + 11h$. This must be at most $450$, giving $19p + 11h \\leq 450$. The minimum hours constraints are $p \\geq 6$ and $h \\geq 3$. The choice with $19p + 11h \\geq 450$ reverses the budget constraint to require spending at least $450$. The choice with $11p + 19h$ swaps the hourly rates between the two workers. The choice with $p \\leq 6$ and $h \\leq 3$ turns the minimum-hour requirements into maximum-hour caps.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM266ZKOU', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations below has two solutions, $(x_1, y_1)$ and $(x_2, y_2)$. What is the value of $x_1 \\cdot x_2$?$$y = 2x - 3$$$$y = x^2 - 5x + 9$$', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$12$"},{"key":"D","text":"$-12$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting $2x - 3 = x^2 - 5x + 9$ gives $x^2 - 7x + 12 = 0$. By Vieta''s formulas, the product of the roots is $\\frac{12}{1} = 12$. This can be confirmed by factoring: $(x - 3)(x - 4) = 0$, giving $x_1 = 3$ and $x_2 = 4$, and $3 \\cdot 4 = 12$. The value $4$ is one of the individual roots, not the product. The value $7$ is the sum of the roots, not the product. The value $-12$ incorrectly applies a negative sign to the constant term in Vieta''s formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM267QXFX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher wants to determine whether a new stretching routine reduces the frequency of lower-back pain in office workers. The researcher recruits $120$ volunteers from a large corporation and randomly assigns $60$ to perform the stretching routine daily for $8$ weeks while the other $60$ follow their normal routine. At the end of the study, the stretching group reports significantly fewer episodes of lower-back pain. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The stretching routine is likely to reduce lower-back pain in all adults."},{"key":"B","text":"The stretching routine likely caused the reduction in lower-back pain for the participants in the study."},{"key":"C","text":"There is an association between the stretching routine and reduced lower-back pain, but causation cannot be established."},{"key":"D","text":"The stretching routine will definitely prevent lower-back pain in office workers."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants were randomly assigned to treatment and control groups, this is a randomized experiment, which can support causal conclusions. The significant result indicates the stretching routine likely caused the reduction in lower-back pain among the study participants. The conclusion about all adults overgeneralizes beyond the study population of office workers who volunteered. The conclusion that causation cannot be established is incorrect because random assignment specifically enables causal inference; that limitation applies only to observational studies. The conclusion that the routine will definitely prevent pain overstates the findings, since statistical significance does not guarantee a universal or absolute effect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27OITMV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution to the equation $x^2 + 3x - 40 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factoring the quadratic: $x^2 + 3x - 40 = (x + 8)(x - 5) = 0$, so $x = -8$ or $x = 5$. The positive solution is $5$. The value $-8$ is the negative root. The value $3$ confuses the coefficient of $x$ with a solution. The value $8$ takes the absolute value of the negative root rather than identifying the actual positive root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27UL7YE', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $5(x + 3) - 2x = 4x + 11$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Distributing 5 on the left side gives $5x + 15 - 2x = 4x + 11$, which simplifies to $3x + 15 = 4x + 11$. Subtracting $3x$ from both sides gives $15 = x + 11$. Subtracting 11 from both sides yields $x = 4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM286NQTP', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'If $9x - 4y = 52$ and $y = 2$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20/3', ARRAY['20/3', '6.666', '6.667'], E'Substituting $y = 2$ into $9x - 4y = 52$ gives $9x - 8 = 52$. Adding 8 to both sides: $9x = 60$. Dividing by 9: $x = \\frac{60}{9} = \\frac{20}{3}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28WM1T7', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A number $m$ satisfies $-1 < 2m - 7 \\leq 9$. Which of the following could be the value of $m$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding $7$ to all three parts of the compound inequality gives $6 < 2m \\leq 16$. Dividing by $2$ yields $3 < m \\leq 8$. The value $5$ lies strictly between $3$ and $8$, so it satisfies the inequality. The value $3$ fails because the left inequality is strict ($m > 3$, not $m \\geq 3$), so $3$ is excluded. The value $9$ exceeds the upper bound of $8$. The value $12$ is well outside the solution interval, resulting from a sign error when isolating $m$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM291XX2Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A biologist studies the relationship between the average daily temperature, in degrees Celsius, and the number of chirps per minute produced by a species of cricket. The line of best fit is $c = 3.5t - 14$, where $c$ is the predicted number of chirps per minute and $t$ is the temperature in degrees Celsius. At a temperature of $22^\\circ\\text{C}$, the actual observed chirp rate is $61$ chirps per minute. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted chirp rate at $t = 22$ is $c = 3.5(22) - 14 = 77 - 14 = 63$. The residual is the actual value minus the predicted value: $61 - 63 = -2$. The distractor $-4$ results from a computation error such as misreading the intercept as $-12$ instead of $-14$, yielding a predicted value of $3.5(22) - 12 = 65$ and a residual of $61 - 65 = -4$. The distractor $2$ reverses the residual formula by computing predicted minus actual ($63 - 61$) instead of actual minus predicted. The distractor $4$ both reverses the formula and makes the same arithmetic error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM297GN0W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has center $(-5, 7)$ and passes through the point $(-5, 18)$. What is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 5)^2 + (y - 7)^2 = 121$"},{"key":"B","text":"$(x - 5)^2 + (y + 7)^2 = 121$"},{"key":"C","text":"$(x + 5)^2 + (y - 7)^2 = 11$"},{"key":"D","text":"$(x + 5)^2 + (y - 18)^2 = 121$"}]$lyceon_json$::jsonb, 'A', NULL, E'The radius is the distance from the center $(-5, 7)$ to the point $(-5, 18)$: $r = |18 - 7| = 11$. The standard equation of a circle with center $(h, k)$ is $(x - h)^2 + (y - k)^2 = r^2$. Substituting: $(x - (-5))^2 + (y - 7)^2 = 11^2$, which gives $(x + 5)^2 + (y - 7)^2 = 121$. The distractor $(x - 5)^2 + (y + 7)^2 = 121$ uses incorrect signs for both the $h$ and $k$ values. The distractor $(x + 5)^2 + (y - 7)^2 = 11$ forgets to square the radius. The distractor $(x + 5)^2 + (y - 18)^2 = 121$ incorrectly uses the given point as the center instead of $(-5, 7)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BI4AV1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-2, 11)$ and $(4, -7)$. What is the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$-\\frac{1}{3}$"},{"key":"D","text":"$\\frac{2}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{-7 - 11}{4 - (-2)} = \\frac{-18}{6} = -3$. The value $3$ results from dropping the negative sign when computing the numerator or denominator. The value $-\\frac{1}{3}$ comes from inverting the fraction, computing $\\frac{6}{-18}$ instead of $\\frac{-18}{6}$. The value $\\frac{2}{3}$ comes from incorrectly calculating the differences as $\\frac{4}{6}$ or a similar setup error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BK7ZTY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $7$ cm and a height of $13$ cm. What is the volume, in cubic centimeters, of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$91\\pi$"},{"key":"B","text":"$182\\pi$"},{"key":"C","text":"$637\\pi$"},{"key":"D","text":"$1274\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 7$ and $h = 13$: $V = \\pi(7)^2(13) = \\pi(49)(13) = 637\\pi$ cubic centimeters. The distractor $91\\pi$ uses $\\pi r h$ instead of $\\pi r^2 h$, computing $7 \\times 13 = 91$. The distractor $182\\pi$ uses $2\\pi r h$ (the lateral surface area formula) instead of the volume formula. The distractor $1274\\pi$ doubles the correct volume, possibly from using the diameter instead of the radius in an intermediate step and then not squaring correctly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BSCY81', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f(x) = -3x^3 + 7x^2 - 4x + 9$. As $x$ increases without bound, which of the following best describes the end behavior of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x)$ increases without bound"},{"key":"B","text":"$f(x)$ decreases without bound"},{"key":"C","text":"$f(x)$ approaches $0$"},{"key":"D","text":"$f(x)$ approaches $9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The leading term is $-3x^3$. Since the leading coefficient is negative and the degree is odd, as $x$ grows large, $f(x)$ decreases without bound. The claim that $f(x)$ increases without bound ignores the negative leading coefficient. The claim that $f(x)$ approaches $0$ confuses polynomial end behavior with that of a rational function with a higher-degree denominator. The claim that $f(x)$ approaches $9$ mistakes the constant term for a horizontal asymptote, which polynomials of degree $1$ or higher do not have.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C79LV3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 + 9x + 13 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = 81 - 4(2)(13) = 81 - 104 = -23$. Since the discriminant is negative, the equation has $0$ distinct real solutions. The answer $1$ would apply only if the discriminant were exactly zero, indicating a repeated root. The answer $2$ assumes a positive discriminant without computing it. The answer $4$ confuses the degree of a polynomial or the number of coefficients with the number of solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CIQ1LY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The function $f$ is defined by $f(x) = 2^x$. If $f(3a - 1) = 32$, what is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Since $f(x) = 2^x$, we have $f(3a - 1) = 2^{3a - 1} = 32$. Writing $32$ as a power of $2$: $32 = 2^5$. Therefore $3a - 1 = 5$, which gives $3a = 6$ and $a = 2$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D6WYVE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 8y = 24$. Line $q$ is perpendicular to line $p$ and passes through the point $(3, -1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{5}$"},{"key":"B","text":"$\\frac{1}{5}$"},{"key":"C","text":"$-\\frac{19}{5}$"},{"key":"D","text":"$\\frac{29}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$ in slope-intercept form: $-8y = -5x + 24$, so $y = \\frac{5}{8}x - 3$, giving slope $\\frac{5}{8}$. The perpendicular slope is $-\\frac{8}{5}$. Using point-slope form with $(3, -1)$: $y - (-1) = -\\frac{8}{5}(x - 3)$, which gives $y + 1 = -\\frac{8}{5}x + \\frac{24}{5}$. So $y = -\\frac{8}{5}x + \\frac{24}{5} - 1 = -\\frac{8}{5}x + \\frac{19}{5}$. The $y$-intercept is $\\frac{19}{5}$. The value $\\frac{1}{5}$ comes from an arithmetic slip when subtracting 1 from $\\frac{24}{5}$, computing $\\frac{24 - 23}{5}$ erroneously. The value $-\\frac{19}{5}$ results from a sign error when handling the perpendicular slope or the point substitution. The value $\\frac{29}{5}$ comes from incorrectly adding 1 to $\\frac{24}{5}$ instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAP879', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore offers a $17\\%$ discount on a textbook originally priced at $\\$62$. What is the sale price of the textbook?', NULL, $lyceon_json$[{"key":"A","text":"$\\$10.54$"},{"key":"B","text":"$\\$45.00$"},{"key":"C","text":"$\\$51.46$"},{"key":"D","text":"$\\$72.54$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount amount is $0.17 \\times 62 = 10.54$. The sale price is $62 - 10.54 = 51.46$ dollars. The distractor $\\$10.54$ gives only the discount amount, not the sale price. The distractor $\\$45.00$ results from a miscalculation of the percentage. The distractor $\\$72.54$ results from adding the discount to the original price instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DEBS0R', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For which value of $k$ does the system $\\begin{cases} 6x - 9y = 15 \\\\ -4x + ky = -10 \\end{cases}$ have infinitely many solutions?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$6$"},{"key":"C","text":"$9$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'B', NULL, E'For infinitely many solutions, the second equation must be a scalar multiple of the first. Dividing the first equation by $3$ gives $2x - 3y = 5$. Multiplying by $-2$ gives $-4x + 6y = -10$, which matches the second equation when $k = 6$. The value $-6$ results from a sign error when applying the scalar multiplier. The value $9$ is the coefficient of $y$ in the original first equation, not the required value after scaling. The value $-9$ confuses the original coefficient with the needed transformation and applies an incorrect sign.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DO5B8W', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h(x) = -2(x - 5)^2 + 13$ has a maximum value. What is this maximum value?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$5$"},{"key":"C","text":"$13$"},{"key":"D","text":"$-13$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $h(x) = a(x - p)^2 + q$ with $a = -2$, and the vertex at $(5, 13)$. Since $a < 0$, the parabola opens downward and the maximum value is $q = 13$. The value $-2$ confuses the leading coefficient with the output value. The value $5$ is the $x$-coordinate of the vertex, not the maximum output. The value $-13$ applies an incorrect sign to the maximum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G606HL', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 11x - 23$. What is the value of $g(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$54$"},{"key":"B","text":"$100$"},{"key":"C","text":"$-54$"},{"key":"D","text":"$46$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 7$: $g(7) = 11(7) - 23 = 77 - 23 = 54$. The value $100$ comes from computing $11 \\times 7 = 77$ and then adding 23 instead of subtracting. The value $-54$ results from a sign error, treating the expression as $23 - 77$. The value $46$ comes from a multiplication error such as computing $11 \\times 7$ as $69$ and then subtracting 23.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I2YLEK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The functions $f(x) = 3x + 2$ and $g(x) = x^2 + x - 5$ are defined for all real numbers. What is the value of $f(g(-3))$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$5$"},{"key":"C","text":"$23$"},{"key":"D","text":"$37$"}]$lyceon_json$::jsonb, 'B', NULL, E'First compute $g(-3) = (-3)^2 + (-3) - 5 = 9 - 3 - 5 = 1$. Then $f(g(-3)) = f(1) = 3(1) + 2 = 5$. The value $1$ is the intermediate result $g(-3)$ alone, stopping before applying $f$. The value $23$ results from a sign error in computing $g(-3)$: treating $(-3)^2 + (-3)$ as $9 + 3 = 12$ instead of $9 - 3 = 6$, giving $g(-3) = 7$ and then $f(7) = 23$. The value $37$ results from computing $g(f(-3))$ in the wrong order: $f(-3) = -7$, then $g(-7) = 49 - 7 - 5 = 37$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I7LOG1', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'The system of equations $\\begin{cases} 3x - 2y = 17 \\\\ 5x + 2y = 39 \\end{cases}$ has a solution $(x, y)$. What is the value of $y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Adding the two equations eliminates $y$: $3x - 2y + 5x + 2y = 17 + 39$, so $8x = 56$ and $x = 7$. Substituting back into the first equation: $3(7) - 2y = 17$, giving $21 - 2y = 17$, so $-2y = -4$ and $y = 2$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2II6RRS', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'Which of the following points lies on the line $4x - 3y = 17$?', NULL, $lyceon_json$[{"key":"A","text":"$(2, 3)$"},{"key":"B","text":"$(1, 5)$"},{"key":"C","text":"$(5, 1)$"},{"key":"D","text":"$(5, -1)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(5, 1)$ into $4x - 3y$: $4(5) - 3(1) = 20 - 3 = 17$, which equals the right side, so this point lies on the line. Substituting $(2, 3)$: $4(2) - 3(3) = 8 - 9 = -1 \\neq 17$, reflecting an arithmetic slip from not checking the substitution carefully. Substituting $(1, 5)$: $4(1) - 3(5) = 4 - 15 = -11 \\neq 17$, reflecting a conceptual gap about how to verify points on a line. Substituting $(5, -1)$: $4(5) - 3(-1) = 20 + 3 = 23 \\neq 17$, a sign error from confusing the sign of the $y$-coordinate with the correct point.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZ59OC', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the system of equations $\\begin{cases} x + y = 13 \\\\ x - y = 5 \\end{cases}$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$9$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations eliminates $y$: $(x + y) + (x - y) = 13 + 5$, so $2x = 18$ and $x = 9$. The value $4$ is $y$, which solves the system but does not answer the question asked. The value $7$ results from an arithmetic error when dividing $18$ by $2$. The value $13$ is the right-hand side of the first equation, not the solution for $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZPVP8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle in the $xy$-plane is defined by the equation $x^2 + y^2 - 14x + 6y - 23 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Complete the square for both variables. Group the $x$ and $y$ terms: $(x^2 - 14x) + (y^2 + 6y) = 23$. For $x$: half of $-14$ is $-7$, and $(-7)^2 = 49$, so $x^2 - 14x + 49 = (x - 7)^2$. For $y$: half of $6$ is $3$, and $3^2 = 9$, so $y^2 + 6y + 9 = (y + 3)^2$. Adding $49$ and $9$ to both sides: $(x - 7)^2 + (y + 3)^2 = 23 + 49 + 9 = 81$. Since $r^2 = 81$, the radius is $r = 9$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KL5ZCX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A swimming pool is being drained at a constant rate. At 10:00 AM, the pool contains 8,400 gallons of water, and at 1:00 PM, it contains 5,250 gallons. Which of the following functions $f(t)$ gives the number of gallons of water in the pool $t$ hours after 10:00 AM?', NULL, $lyceon_json$[{"key":"A","text":"$f(t) = 8400 - 1050t$"},{"key":"B","text":"$f(t) = 8400 - 3150t$"},{"key":"C","text":"$f(t) = 5250 - 1050t$"},{"key":"D","text":"$f(t) = 8400 + 1050t$"}]$lyceon_json$::jsonb, 'A', NULL, E'The pool loses $8400 - 5250 = 3150$ gallons over 3 hours, giving a rate of $\\frac{3150}{3} = 1050$ gallons per hour. Since the pool is draining, the rate is negative: $f(t) = 8400 - 1050t$. The function $f(t) = 8400 - 3150t$ uses the total change of 3150 as the hourly rate, failing to divide by 3. The function $f(t) = 5250 - 1050t$ uses the ending amount as the initial value instead of 8400. The function $f(t) = 8400 + 1050t$ adds the rate instead of subtracting, meaning the pool would be filling rather than draining.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"unit_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L8NU9M', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The line $y = kx + 5$ is tangent to the parabola $y = x^2 + 14x + 54$. If $k > 0$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$14$"},{"key":"C","text":"$28$"},{"key":"D","text":"$54$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting $kx + 5 = x^2 + 14x + 54$ gives $x^2 + (14 - k)x + 49 = 0$. For tangency, the discriminant must equal zero: $(14 - k)^2 - 4(1)(49) = 0$, so $(14 - k)^2 = 196$. Taking square roots: $14 - k = \\pm 14$, which gives $k = 0$ or $k = 28$. Since $k > 0$, the answer is $k = 28$. The value $7$ is the square root of $49$ but does not arise from the discriminant condition. The value $14$ is the coefficient of $x$ in the parabola, not a solution. The value $54$ is the constant term of the parabola.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NBTC3W', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'The polynomial $2x^3 + 7x^2 - 27x + 18$ is divisible by $(x + 6)$. Which expression is equivalent to $\\frac{2x^3 + 7x^2 - 27x + 18}{x + 6}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 + 5x - 3$"},{"key":"B","text":"$2x^2 - 5x + 3$"},{"key":"C","text":"$2x^2 - 5x - 3$"},{"key":"D","text":"$x^2 - 5x + 3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using polynomial long division or synthetic division with $-6$: divide $2x^3 + 7x^2 - 27x + 18$ by $(x + 6)$. First term: $2x^3 \\div x = 2x^2$. Multiply: $2x^2(x + 6) = 2x^3 + 12x^2$. Subtract to get $-5x^2 - 27x$. Next term: $-5x^2 \\div x = -5x$. Multiply: $-5x(x + 6) = -5x^2 - 30x$. Subtract to get $3x + 18$. Last term: $3x \\div x = 3$. Multiply: $3(x + 6) = 3x + 18$. Remainder is $0$, confirming the quotient is $2x^2 - 5x + 3$. The distractor $2x^2 + 5x - 3$ has the signs of the last two terms reversed. The distractor $2x^2 - 5x - 3$ has a sign error on the constant term. The distractor $x^2 - 5x + 3$ drops the leading coefficient, reflecting a misunderstanding of polynomial division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NNACHF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $9$ units and a central angle that measures $120^\\circ$. What is the length of the arc intercepted by this central angle?', NULL, $lyceon_json$[{"key":"A","text":"$3\\pi$"},{"key":"B","text":"$6\\pi$"},{"key":"C","text":"$27\\pi$"},{"key":"D","text":"$18\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'Arc length is calculated as $\\dfrac{\\theta}{360} \\times 2\\pi r$. Substituting the given values: $\\dfrac{120}{360} \\times 2\\pi(9) = \\dfrac{1}{3} \\times 18\\pi = 6\\pi$. The distractor $3\\pi$ results from using $\\pi r$ instead of $2\\pi r$ in the circumference part, computing $\\dfrac{1}{3} \\times 9\\pi = 3\\pi$. The distractor $27\\pi$ confuses arc length with sector area, computing $\\dfrac{1}{3} \\times \\pi r^2 = \\dfrac{1}{3} \\times 81\\pi = 27\\pi$. The distractor $18\\pi$ ignores the central angle entirely and gives the full circumference $2\\pi(9) = 18\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PD8F5W', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'If $y = 2x + 1$ and $y = x^2 + 3x - 5$, what is the larger value of $x$ that satisfies both equations?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the two expressions for $y$ equal: $2x + 1 = x^2 + 3x - 5$, which rearranges to $x^2 + x - 6 = 0$. Factoring gives $(x + 3)(x - 2) = 0$, so $x = -3$ or $x = 2$. The larger value is $2$. The value $-3$ is the smaller of the two solutions. The value $-1$ results from an arithmetic error such as incorrectly combining the linear terms. The value $5$ confuses a $y$-coordinate with an $x$-value, since at $x = 2$ the line gives $y = 5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PDZYQQ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If $(x^3)^4 \\cdot x^5 = x^n$, what is the value of $n$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Apply the power rule: $(x^3)^4 = x^{3 \\cdot 4} = x^{12}$. Then apply the product rule: $x^{12} \\cdot x^5 = x^{12 + 5} = x^{17}$. Therefore $n = 17$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R04DFS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'What is the solution to the equation $\\frac{9}{x - 3} + 4 = \\frac{x + 18}{x - 3}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Multiplying both sides by $(x - 3)$ gives $9 + 4(x - 3) = x + 18$. Expanding: $9 + 4x - 12 = x + 18$, which simplifies to $4x - 3 = x + 18$. Solving: $3x = 21$, so $x = 7$. Checking: $\\frac{9}{4} + 4 = \\frac{9}{4} + \\frac{16}{4} = \\frac{25}{4}$, and $\\frac{25}{4} = \\frac{25}{4}$. The solution is valid since $x = 7 \\neq 3$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R32VCU', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'The solution set of the inequality $|4x - 9| < 7$ can be written as $a < x < b$. What is the value of $a + b$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{2}$"},{"key":"B","text":"$\\frac{9}{2}$"},{"key":"C","text":"$4$"},{"key":"D","text":"$\\frac{11}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The inequality $|4x - 9| < 7$ splits into $-7 < 4x - 9 < 7$. Adding $9$ to all parts gives $2 < 4x < 16$. Dividing by $4$ yields $\\frac{1}{2} < x < 4$. So $a = \\frac{1}{2}$ and $b = 4$, giving $a + b = \\frac{1}{2} + 4 = \\frac{9}{2}$. The value $\\frac{7}{2}$ results from correctly solving $a = \\frac{1}{2}$ and $b = 4$ but then computing $b - a = 4 - \\frac{1}{2} = \\frac{7}{2}$ instead of $a + b$. The value $4$ comes from only computing $b$ without adding $a$. The value $\\frac{11}{2}$ arises from a sign error when splitting the absolute value, yielding $a = \\frac{3}{2}$ instead of $\\frac{1}{2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R7B4UU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $JKL$, angle $L = 90^\\circ$. If $\\tan(J) = \\dfrac{3}{7}$ and the side $KL = 15$, what is the length of side $JL$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '35', ARRAY['35'], E'In right triangle $JKL$ with the right angle at $L$, the side $KL$ is opposite angle $J$ and the side $JL$ is adjacent to angle $J$. Therefore $\\tan(J) = \\dfrac{KL}{JL}$. Substituting the given values: $\\dfrac{3}{7} = \\dfrac{15}{JL}$. Cross-multiplying gives $3 \\cdot JL = 7 \\cdot 15 = 105$, so $JL = 35$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RP0IMC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $DEF$, angle $F = 90^\\circ$. If $\\sin(D) = \\dfrac{7}{25}$, what is $\\cos(E)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\dfrac{7}{25}$"},{"key":"B","text":"$\\dfrac{24}{25}$"},{"key":"C","text":"$\\dfrac{7}{24}$"},{"key":"D","text":"$\\dfrac{25}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In a right triangle with the right angle at $F$, angles $D$ and $E$ are complementary, meaning $D + E = 90^\\circ$. A fundamental identity states that $\\sin(D) = \\cos(90^\\circ - D) = \\cos(E)$. Therefore $\\cos(E) = \\dfrac{7}{25}$. The distractor $\\dfrac{24}{25}$ confuses $\\cos(E)$ with $\\cos(D)$, using the adjacent leg over hypotenuse for angle $D$ instead of recognizing the complementary relationship. The distractor $\\dfrac{7}{24}$ incorrectly computes $\\tan(D)$ instead of $\\cos(E)$. The distractor $\\dfrac{25}{7}$ inverts the fraction, confusing sine with cosecant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SPSWQI', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'grid_in', E'If $7x^3 \\cdot 3x^4 = 21x^n$, what is the value of $n$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'When multiplying powers with the same base, add the exponents: $7x^3 \\cdot 3x^4 = (7 \\cdot 3)(x^{3+4}) = 21x^7$. Therefore $n = 7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ST1P1W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages, in years, of $9$ employees at a company are $24, 28, 31, 35, 37, 41, 44, 49, 71$. If the oldest employee ($71$ years old) leaves the company, how does the mean age of the remaining employees change?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases by approximately $3.9$ years."},{"key":"B","text":"The mean decreases by approximately $2.4$ years."},{"key":"C","text":"The mean increases by approximately $2.4$ years."},{"key":"D","text":"The mean stays the same."}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of all $9$ ages is $24 + 28 + 31 + 35 + 37 + 41 + 44 + 49 + 71 = 360$. The original mean is $\\frac{360}{9} = 40$. After removing $71$, the sum is $360 - 71 = 289$ over $8$ employees, giving a new mean of $\\frac{289}{8} = 36.125$. The decrease is $40 - 36.125 = 3.875$, which is approximately $3.9$ years. The distractor stating a decrease of approximately $2.4$ years results from an arithmetic error in the division. The distractor stating the mean increases by $2.4$ years reverses the direction of the effect. The distractor stating the mean stays the same ignores that removing a value well above the mean pulls the mean downward.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SZOF6F', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ satisfies $f(2) = 17$ and $f(9) = -18$. What is $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-27$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $m = \\frac{-18 - 17}{9 - 2} = \\frac{-35}{7} = -5$. Using point-slope form with $(2, 17)$: $f(x) = -5(x - 2) + 17 = -5x + 10 + 17 = -5x + 27$. Therefore $f(0) = -5(0) + 27 = 27$. The value $7$ comes from computing the slope correctly as $-5$ and the adjustment $(-5)(0 - 2) = 10$, but subtracting instead of adding: $17 - 10 = 7$. The value $-27$ results from a sign error in computing the $y$-intercept, negating the result. The value $22$ comes from an arithmetic slip such as computing $-5(2) + 17 = -10 + 17 = 7$ and then incorrectly adjusting to find $f(0) = 17 + 5 = 22$ by adding one slope step in the wrong direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T1I4TS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 - 25}{2x + 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x - 5$"},{"key":"B","text":"$2x + 5$"},{"key":"C","text":"$2x^2 - 5$"},{"key":"D","text":"$4x - 5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Recognize that $4x^2 - 25 = (2x)^2 - 5^2 = (2x - 5)(2x + 5)$ is a difference of squares. Dividing by $(2x + 5)$ gives $2x - 5$. The distractor $2x + 5$ results from a sign error in factoring the difference of squares. The distractor $2x^2 - 5$ results from incorrectly dividing term-by-term without factoring. The distractor $4x - 5$ results from dividing only the coefficient of $x^2$ by $2$ without recognizing the squared binomial structure.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U2E6HB', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A farm sells organic eggs for $\\$7$ per dozen and free-range eggs for $\\$4$ per dozen. In one week, the farm sold a total of $23$ dozen and earned $\\$125$. How many dozen organic eggs were sold?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$11$"},{"key":"C","text":"$12$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $g$ be dozen organic and $f$ be dozen free-range. The system is $g + f = 23$ and $7g + 4f = 125$. From the first equation, $f = 23 - g$. Substituting: $7g + 4(23 - g) = 125$, so $7g + 92 - 4g = 125$, giving $3g = 33$ and $g = 11$. The value $9$ results from an arithmetic error such as computing $125 - 92 = 33$ but then dividing by a wrong coefficient, e.g. $33 / 3$ misread as $27 / 3 = 9$. The value $12$ comes from swapping the prices in the revenue equation: $4g + 7(23 - g) = 125$ gives $-3g = -36$, so $g = 12$. The value $14$ corresponds to the number of free-range dozen ($23 - 11 = 12$, not $14$) and also reflects misreading which quantity the question asks for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UKVT43', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A chemical solution is prepared by mixing compound $X$ and compound $Y$ in a ratio of $7:3$ by mass. If a technician needs to prepare $1{,}340$ grams of this solution, how many grams of compound $X$ are needed?', NULL, $lyceon_json$[{"key":"A","text":"$402$"},{"key":"B","text":"$670$"},{"key":"C","text":"$938$"},{"key":"D","text":"$1{,}004$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of compound $X$ to compound $Y$ is $7:3$, so the total number of parts is $7 + 3 = 10$. Compound $X$ constitutes $\\frac{7}{10}$ of the solution. Therefore, the mass of compound $X$ is $\\frac{7}{10} \\times 1{,}340 = 938$ grams. The distractor $402$ results from incorrectly computing $\\frac{3}{10} \\times 1{,}340$, which gives the amount of compound $Y$ instead of $X$. The distractor $670$ results from dividing $1{,}340$ by $2$, ignoring the ratio entirely and assuming equal parts. The distractor $1{,}004$ results from an arithmetic error when multiplying $\\frac{7}{10} \\times 1{,}340$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UWKF74', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of $450$ voters in a city found that $58\\%$ support a proposed parks initiative, with a margin of error of $4.1$ percentage points at a $95\\%$ confidence level. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all voters in the city support the initiative."},{"key":"B","text":"Between $53.9\\%$ and $62.1\\%$ of all voters in the city are likely to support the initiative."},{"key":"C","text":"The margin of error guarantees that the true population percentage is $58\\%$."},{"key":"D","text":"If the survey were repeated, $95\\%$ of respondents would support the initiative."}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval is $58\\% \\pm 4.1\\%$, which gives the range $53.9\\%$ to $62.1\\%$. At a $95\\%$ confidence level, this means we can be $95\\%$ confident that the true proportion of all voters in the city who support the initiative falls between $53.9\\%$ and $62.1\\%$. The claim that exactly $58\\%$ support the initiative is incorrect because the sample statistic is an estimate, not an exact population parameter. The claim that the margin of error guarantees the true value is incorrect because a margin of error does not guarantee a specific value; it provides a range within which the true value is likely to fall at the stated confidence level. The claim that $95\\%$ of respondents would support the initiative in a repeated survey is incorrect because the $95\\%$ confidence level refers to the reliability of the interval estimation method, not to the percentage of respondents who would give a particular answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W0KBAE', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A mechanic charges a flat diagnostic fee of $\\$47$ plus $\\$83$ per hour of labor. A second mechanic charges no diagnostic fee but $\\$109$ per hour. For how many hours of labor would both mechanics charge the same total amount?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{47}{26}$"},{"key":"B","text":"$\\frac{47}{192}$"},{"key":"C","text":"$\\frac{47}{109}$"},{"key":"D","text":"$\\frac{83}{109}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the costs equal: $47 + 83h = 109h$. Subtracting $83h$ from both sides gives $47 = 26h$, so $h = \\frac{47}{26}$. The value $\\frac{47}{192}$ results from incorrectly adding the hourly rates ($83 + 109 = 192$) instead of finding their difference. The value $\\frac{47}{109}$ comes from setting up $47 = 109h$ and ignoring the first mechanic''s hourly rate entirely. The value $\\frac{83}{109}$ comes from forming a ratio of the two hourly rates, which does not represent the equation for equal total cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WDTGRW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $6x^2 + 19x - 7$?', NULL, $lyceon_json$[{"key":"A","text":"$(6x - 1)(x + 7)$"},{"key":"B","text":"$(3x + 1)(2x - 7)$"},{"key":"C","text":"$(3x - 7)(2x + 1)$"},{"key":"D","text":"$(3x - 1)(2x + 7)$"}]$lyceon_json$::jsonb, 'D', NULL, E'To factor $6x^2 + 19x - 7$, find two numbers that multiply to $6 \\cdot (-7) = -42$ and add to $19$: those are $21$ and $-2$. Rewrite: $6x^2 + 21x - 2x - 7 = 3x(2x + 7) - 1(2x + 7) = (3x - 1)(2x + 7)$. The distractor $(6x - 1)(x + 7)$ expands to $6x^2 + 41x - 7$, an incorrect grouping. The distractor $(3x + 1)(2x - 7)$ expands to $6x^2 - 19x - 7$, reflecting a sign error on the middle term. The distractor $(3x - 7)(2x + 1)$ expands to $6x^2 - 11x - 7$, reflecting an incorrect factor pairing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WPBELO', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $5(2a - 9) + 3a$?', NULL, $lyceon_json$[{"key":"A","text":"$7a - 45$"},{"key":"B","text":"$13a - 9$"},{"key":"C","text":"$13a - 45$"},{"key":"D","text":"$10a - 9$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing gives $5 \\cdot 2a - 5 \\cdot 9 + 3a = 10a - 45 + 3a = 13a - 45$. The distractor $7a - 45$ results from subtracting $3a$ instead of adding it (sign error). The distractor $13a - 9$ results from failing to distribute the $5$ to the $-9$ term. The distractor $10a - 9$ results from both omitting the $+3a$ and failing to distribute $5$ to $-9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WY36VW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $2(x + 9) = 52$?', NULL, $lyceon_json$[{"key":"A","text":"$17$"},{"key":"B","text":"$35$"},{"key":"C","text":"$43$"},{"key":"D","text":"$-17$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing both sides of $2(x + 9) = 52$ by 2 gives $x + 9 = 26$. Subtracting 9 from both sides yields $x = 17$. The value $35$ results from adding 9 to 26 instead of subtracting. The value $43$ comes from failing to divide by 2 first, solving $x + 9 = 52$ directly. The value $-17$ results from a sign error when isolating $x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XFJAOP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures $(7x - 13)^\\circ$. The co-interior angle (same-side interior angle) on the same transversal measures $(4x + 28)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$17$"},{"key":"C","text":"$19$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'Co-interior angles (same-side interior angles) formed by parallel lines and a transversal are supplementary, meaning they sum to $180^\\circ$. Setting up the equation: $(7x - 13) + (4x + 28) = 180$, which simplifies to $11x + 15 = 180$, so $11x = 165$ and $x = 15$. The distractor $17$ results from incorrectly setting the angles equal to each other (as if they were alternate interior angles): $7x - 13 = 4x + 28$ gives $3x = 41$, and then rounding or mis-solving to get $17$. The distractor $19$ arises from mistakenly setting each angle equal to $90^\\circ$ or another conceptual error. The distractor $22$ comes from an arithmetic slip such as dividing $165$ by an incorrect coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XSYEPQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of $40$ students, $23$ study French, $19$ study Spanish, and $7$ study both French and Spanish. If a student is selected at random from those who study at least one of the two languages, what is the probability that the student studies French but not Spanish?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{16}{35}$"},{"key":"B","text":"$\\frac{2}{5}$"},{"key":"C","text":"$\\frac{23}{40}$"},{"key":"D","text":"$\\frac{19}{35}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By inclusion-exclusion, the number of students studying at least one language is $23 + 19 - 7 = 35$. The number studying French but not Spanish is $23 - 7 = 16$. The probability is $\\frac{16}{35}$. The distractor $\\frac{2}{5}$ results from computing $\\frac{16}{40}$, which incorrectly uses the total class size of $40$ instead of the $35$ students who study at least one language. The distractor $\\frac{23}{40}$ uses all French students ($23$) divided by the total class, ignoring both the restriction to at least one language and the need to exclude those studying both. The distractor $\\frac{19}{35}$ incorrectly uses the number of Spanish students ($19$) instead of the number studying French but not Spanish ($16$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XV7FYZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47^\\circ$ and the measure of angle $Q$ is $68^\\circ$. What is the measure, in degrees, of the exterior angle at vertex $R$?', NULL, $lyceon_json$[{"key":"A","text":"$65^\\circ$"},{"key":"B","text":"$115^\\circ$"},{"key":"C","text":"$125^\\circ$"},{"key":"D","text":"$133^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of interior angles in a triangle is $180^\\circ$. Angle $R = 180^\\circ - 47^\\circ - 68^\\circ = 65^\\circ$. The exterior angle at $R$ is supplementary to the interior angle, so it equals $180^\\circ - 65^\\circ = 115^\\circ$. The distractor $65^\\circ$ gives the interior angle at $R$ rather than the exterior angle. The distractor $125^\\circ$ results from an arithmetic error when subtracting ($180 - 47 - 68$ computed incorrectly as $55$, then $180 - 55 = 125$). The distractor $133^\\circ$ comes from incorrectly adding the two given angles and treating that as the exterior angle ($47 + 68 = 115$, then confusing steps to get $133$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZHI8HS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A triangle has a base of $19$ inches and a height of $8$ inches. What is the area, in square inches, of the triangle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '76', ARRAY['76'], E'The area of a triangle is $A = \\dfrac{1}{2} \\times \\text{base} \\times \\text{height}$. Substituting: $A = \\dfrac{1}{2} \\times 19 \\times 8 = \\dfrac{152}{2} = 76$ square inches.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZXTAYN', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{8x^3 + 27}{2x + 3}$ can be written in the form $ax^2 + bx + c$, where $a$, $b$, and $c$ are constants. What is the value of $a - b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'Recognize that $8x^3 + 27 = (2x)^3 + 3^3$ is a sum of cubes. Using the identity $u^3 + v^3 = (u + v)(u^2 - uv + v^2)$ with $u = 2x$ and $v = 3$: $(2x + 3)(4x^2 - 6x + 9)$. Dividing by $(2x + 3)$ gives $4x^2 - 6x + 9$, so $a = 4$, $b = -6$, and $c = 9$. Therefore $a - b + c = 4 - (-6) + 9 = 4 + 6 + 9 = 19$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20DH6XX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Although the Ottoman miniature painting tradition is often characterized as highly formulaic, art historian Serpil Bagci argues that this characterization ______ the subtle individuality present in many works. Close examination reveals that painters frequently deviated from prescribed compositions, introducing personal flourishes that distinguish one artist''s renderings from another''s.', $lyceon_json$[{"key":"A","text":"scrutinizes"},{"key":"B","text":"obscures"},{"key":"C","text":"fabricates"},{"key":"D","text":"underscores"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that calling the tradition "formulaic" misses the individuality present in many works, so the characterization hides or conceals that individuality. "Obscures" means to make unclear or conceal, which fits this meaning precisely. "Scrutinizes" means to examine closely, which is the opposite of hiding something. "Fabricates" means to invent or manufacture something false, but the passage does not claim the characterization invents the individuality. "Underscores" means to emphasize, which contradicts the passage''s argument that the characterization fails to reveal the individuality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21JBMKS', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes how Text 2''s findings relate to the hypothesis presented in Text 1?', E'Text 1: Paleontologist Sofia Ekblom has proposed that the gigantic body size of certain Late Cretaceous sauropod dinosaurs, such as Argentinosaurus, was driven primarily by an evolutionary arms race with predators. Under this hypothesis, larger body size conferred protection against theropod predators, creating a selection pressure that favored increasingly massive individuals over successive generations.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW231NYM8', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Behavioral ecologist Priya Menon has argued that cooperative breeding in certain bird species evolved primarily as a response to unpredictable food availability, with helpers at the nest buffering against seasons of scarcity. Her longitudinal study of azure-crowned jays in the Western Ghats showed that nests with helpers produced significantly more fledglings during drought years than those without. _______ a parallel investigation by ornithologist Kenji Fukuda found that in a closely related species, the Ryukyu jay, helpers were most commonly recruited during years of abundant resources rather than scarce ones, complicating the narrative that cooperative breeding is strictly a hedge against environmental uncertainty.', $lyceon_json$[{"key":"A","text":"By the same reasoning,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"That said,"},{"key":"D","text":"To illustrate this further with additional evidence,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "That said," because the passage pivots from Menon''s evidence supporting the scarcity-driven hypothesis to Fukuda''s contrasting finding that helpers appear during abundance, which introduces a qualification to the prior claim without wholly dismissing it. "By the same reasoning" incorrectly signals that Fukuda''s finding follows from the same logic, when in fact it complicates the scarcity-driven hypothesis. "Accordingly" implies that Fukuda''s finding is a direct consequence of Menon''s results, but the two findings point in opposite directions regarding when helpers are recruited. "To illustrate this further with additional evidence" wrongly signals that Fukuda''s study reinforces Menon''s argument, when it instead presents a countervailing pattern that challenges the universality of the scarcity hypothesis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23UQAHA', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, which choice best describes a difference in how the two authors explain the decline of pollinator populations?', E'Text 1: Entomologist Priya Vasudeva attributes the decline in wild bee populations primarily to habitat fragmentation. As agricultural expansion converts wildflower meadows and hedgerows into monoculture cropland, bees lose the diverse foraging resources they depend on throughout their life cycles. Vasudeva emphasizes that even narrow strips of restored wildflower habitat along field margins can substantially reverse local population declines.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25FGPVX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead geochemist nor the two field assistants _____ in the latest core samples diverged so sharply from those predicted by the team''s computational model, a discrepancy that prompted an immediate recalibration of the mass spectrometer.', $lyceon_json$[{"key":"A","text":"was able to explain why the sulfur isotope ratios"},{"key":"B","text":"were able to explain why the sulfur isotope ratios"},{"key":"C","text":"has been able to explain why the sulfur isotope ratios"},{"key":"D","text":"is able to explain why the sulfur isotope ratios"}]$lyceon_json$::jsonb, 'B', NULL, E'In a "neither...nor" construction, the verb agrees with the subject closest to it. Here, the closer subject is "the two field assistants," which is plural, so the plural verb "were" is required. The singular "was" would be correct only if the closer subject were singular. The singular present perfect "has been" fails on two counts: it does not agree with the plural nearer subject, and it shifts the tense away from the simple past established by "diverged" and "prompted" elsewhere in the sentence. The singular present "is" similarly mismatches the plural nearer subject and introduces a tense inconsistency with the past-tense context of the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27Y8WJS', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the deep-water anglerfish have noted that the species displays remarkable ______ when hunting: it remains almost entirely motionless for hours, waiting for prey to drift within reach of its bioluminescent lure before striking with sudden speed.', $lyceon_json$[{"key":"A","text":"patience"},{"key":"B","text":"belligerence"},{"key":"C","text":"fragility"},{"key":"D","text":"ostentation"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the anglerfish remaining motionless for hours waiting for prey, which directly indicates patience. "Belligerence" (aggressive hostility) contradicts the motionless behavior described. "Fragility" (delicateness or weakness) has no connection to the hunting strategy of waiting. "Ostentation" (showy display intended to impress) mischaracterizes the functional purpose of the lure, which is predatory rather than exhibitionist.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28GT0ZE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Philosopher Kwame Anthony Appiah contends that the concept of a monolithic "Western civilization" is largely a retrospective construction. The intellectual traditions now grouped under that label were, in their own eras, far more ______ than contemporary accounts suggest: Greek philosophy drew on Egyptian and Babylonian thought, medieval European scholars relied heavily on Arabic translations, and Enlightenment thinkers frequently cited Chinese governance as a model.', $lyceon_json$[{"key":"A","text":"hermetic"},{"key":"B","text":"polemical"},{"key":"C","text":"prescriptive"},{"key":"D","text":"porous"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage emphasizes that intellectual traditions drew freely from diverse external sources, meaning the boundaries between them were permeable and allowed ideas to pass through. "Porous" precisely captures this permeability. "Hermetic" means completely sealed or airtight, the opposite of what the passage describes. "Polemical" means involving strongly critical argument or dispute, which has no connection to the permeability and cross-cultural exchange described. "Prescriptive" means relating to rules or norms, which does not describe the permeability of intellectual boundaries.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A7CR1Y', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The marine biologist Dr. Yumiko Tanabe has spent over a decade studying bioluminescent organisms in the Mariana _____ identified a previously unknown species of glowing jellyfish at a depth of 4,700 meters.', $lyceon_json$[{"key":"A","text":"Trench, her team recently"},{"key":"B","text":"Trench; her team recently"},{"key":"C","text":"Trench her team recently"},{"key":"D","text":"Trench, her team, recently"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a semicolon to join two independent clauses: "Dr. Yumiko Tanabe has spent over a decade studying bioluminescent organisms in the Mariana Trench" and "her team recently identified a previously unknown species of glowing jellyfish at a depth of 4,700 meters." The version using a comma between the two independent clauses creates a comma splice, which is not acceptable in Standard English. The version omitting punctuation entirely produces a run-on sentence. The version inserting commas around "her team" incorrectly treats that phrase as a parenthetical, disrupting the meaning of the second clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AASQMF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the sentence "Their webbed feet make them exceptionally strong swimmers" in the text as a whole?', E'Capybaras, the world''s largest rodents, are native to South America and can weigh up to 65 kilograms. They are semi-aquatic, spending much of their time in or near water, where they feed on grasses and aquatic plants. Their webbed feet make them exceptionally strong swimmers.Unlike many rodent species, capybaras are highly social, living in groups that can number as many as forty individuals.', $lyceon_json$[{"key":"A","text":"It provides a physical adaptation that supports a behavioral trait described earlier in the passage"},{"key":"B","text":"It challenges a widespread assumption about the dietary habits of capybaras"},{"key":"C","text":"It establishes a contrast between capybaras and other semi-aquatic mammals found in the same region"},{"key":"D","text":"It introduces a classification system used by zoologists studying large rodent populations worldwide"}]$lyceon_json$::jsonb, 'A', NULL, E'The quoted sentence about webbed feet describes a physical adaptation (webbed feet) that explains how capybaras are strong swimmers, directly supporting the earlier statement that they spend much time in or near water. The passage does not challenge any assumption about diet, so the option about dietary habits is unsupported. The passage never mentions other semi-aquatic mammals, so the contrast option introduces information absent from the text. The passage does not discuss any zoological classification system, making that option entirely fabricated.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BZN82S', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the 1970s, archaeologist Tunde Adeyemi documented extensive trade networks linking ancient settlements along the Niger River. His excavations uncovered imported obsidian tools at sites more than 800 kilometers from the nearest volcanic source. _______ recent isotopic analyses by geochemist Mariana Solano have traced the obsidian to a previously unidentified quarry in the Jos Plateau region, suggesting that the trade routes may have been shorter and more direct than Adeyemi originally estimated.', $lyceon_json$[{"key":"A","text":"To corroborate this interpretation,"},{"key":"B","text":"As a consequence of these findings,"},{"key":"C","text":"However,"},{"key":"D","text":"Similarly, building on this framework,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "However," because Solano''s isotopic analyses challenge Adeyemi''s original interpretation by showing the obsidian source was closer than he believed, indicating a contrast between the two researchers'' conclusions. "To corroborate this interpretation" wrongly suggests Solano''s work supports Adeyemi''s claim, when it actually revises it. "As a consequence of these findings" implies a causal chain rather than a correction of a prior estimate. "Similarly, building on this framework" implies agreement and extension, but Solano''s findings reduce the estimated distance of the trade routes, contradicting Adeyemi''s original assessment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D9TO0T', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2019 survey of urban beekeeping practices across eleven _____ that rooftop hives produced, on average, 23 percent more honey per colony than hives maintained at ground level in the same neighborhoods.', $lyceon_json$[{"key":"A","text":"municipalities, researchers found"},{"key":"B","text":"municipalities; researchers found"},{"key":"C","text":"municipalities. Researchers found"},{"key":"D","text":"municipalities researchers found"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice uses a comma after "municipalities" because the introductory prepositional phrase "In a 2019 survey of urban beekeeping practices across eleven municipalities" precedes the main clause "researchers found that rooftop hives produced..." A comma is the standard punctuation after a long introductory phrase. Using a semicolon after "municipalities" is incorrect because what precedes it is not an independent clause. Using a period creates the same problem: the introductory phrase cannot stand alone as a sentence. Omitting punctuation entirely makes the sentence difficult to parse and violates conventions for setting off introductory elements.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EI0K4V', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Geochemist Clair Patterson spent years developing an ultrapure laboratory environment to measure the true isotopic ratios of lead in ancient rock samples. His 1956 results yielded an age of 4.55 billion years for the Earth, a figure that has withstood decades of subsequent refinement and remains the accepted estimate today.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EQ423U', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Architectural historian Mei-Ling Tsao has studied the clay brick buildings of Fujian province, noting that many structures built in the seventeenth century remain structurally sound today despite never receiving modern reinforcement. Tsao attributes their durability to the region''s traditional practice of mixing sticky rice paste into the morite between bricks. Laboratory analysis has confirmed that this rice-paste mortar forms a denser crystalline structure than conventional lime mortar alone. Given these findings, it is reasonable to conclude that ________', $lyceon_json$[{"key":"A","text":"the addition of sticky rice paste contributed to the formation of a mortar with superior structural properties, helping to explain the buildings' longevity"},{"key":"B","text":"seventeenth-century Fujian builders possessed a comprehensive understanding of the chemical processes involved in crystalline bond formation within mortar compounds"},{"key":"C","text":"all clay brick structures in Fujian province that were built without sticky rice mortar have deteriorated beyond the point of structural viability by the present day"},{"key":"D","text":"modern construction engineers have recently begun incorporating sticky rice paste into commercial mortar formulations as a direct result of Tsao's published research findings on Fujian architecture"}]$lyceon_json$::jsonb, 'A', NULL, E'The text establishes that rice-paste mortar produces denser crystalline structures and that buildings using it have endured for centuries. The conclusion that rice paste contributed to superior mortar properties that explain the longevity follows directly from the stated evidence. The claim about builders possessing comprehensive chemical understanding overreaches; practical knowledge of a technique does not imply understanding of its chemistry. The claim that all buildings without rice mortar have deteriorated makes an absolute assertion unsupported by the text. The claim about modern engineers incorporating rice paste in response to Tsao''s research introduces information with no basis in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FERGHG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Folklorist Zora Neale Hurston''s 1935 work "Mules and Men" was initially dismissed by some contemporaries as lacking scholarly rigor because it incorporated narrative storytelling techniques uncommon in academic ethnographies of the period. Richard Wright, for instance, criticized the book for presenting folklore without sufficient socioeconomic analysis. However, later scholars have recognized that Hurston''s approach was methodologically deliberate: by embedding herself within the communities she studied and reproducing their speech patterns and storytelling traditions, she preserved dimensions of cultural life that more detached observational methods would have missed entirely.', $lyceon_json$[{"key":"A","text":"It presents an early negative reception of a scholarly work and then explains why later assessments viewed the methodology as a strength"},{"key":"B","text":"It contrasts two ethnographic methods and argues that one is categorically superior to the other in every possible research context and application"},{"key":"C","text":"It recounts the biographical circumstances that led Hurston to abandon conventional academic writing in favor of fiction"},{"key":"D","text":"It summarizes the plot of a literary work and evaluates its commercial success relative to other publications of the same decade"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first describes how Hurston''s work was dismissed for lacking scholarly rigor, then explains how later scholars recognized that her methodology was deliberately chosen and captured cultural dimensions other methods would miss. This matches the option describing an early negative reception followed by a later reassessment of the methodology as a strength. The option about categorical superiority overstates the passage''s claim, which says Hurston''s method captured what detached methods missed, not that it is superior in every context. The passage never mentions biographical circumstances leading Hurston to abandon academic writing. The passage does not discuss the plot of the work or its commercial success.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JO1AMI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architect Lena Johansson, whose firm specializes in sustainable housing for subarctic _____ that uses geothermal heat pumps paired with triple-glazed aerogel windows to maintain interior temperatures above 18 degrees Celsius even during prolonged polar darkness.', $lyceon_json$[{"key":"A","text":"communities, recently unveiled a prototype dwelling"},{"key":"B","text":"communities recently unveiled a prototype dwelling"},{"key":"C","text":"communities; recently unveiled a prototype dwelling"},{"key":"D","text":"communities, she recently unveiled a prototype dwelling"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence contains a nonrestrictive relative clause beginning with "whose firm specializes in sustainable housing for subarctic communities." This clause must be closed with a comma before the sentence continues with the main verb. The correct choice places the closing comma after "communities" and continues with the adverb "recently" modifying the main verb "unveiled." Omitting the closing comma after the nonrestrictive clause violates the convention that paired commas must set off such clauses. Using a semicolon after "communities" incorrectly splits the sentence, since what follows the semicolon ("recently unveiled a prototype dwelling...") lacks a subject and is not an independent clause. Inserting "she" after the comma creates a redundant subject, since "The architect Lena Johansson" already serves as the subject of "unveiled," producing a grammatically faulty double-subject construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JY1BA4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Mycologist Elara Voss has spent over a decade cataloging bioluminescent fungi in the cloud forests of Central America. Her research has revealed that certain species emit light primarily during the rainy season, when spore dispersal is most critical. _______ Voss has proposed that the bioluminescence serves as a signal to nocturnal insects, which then carry spores to new substrates across the forest floor.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"On the basis of these findings,"},{"key":"C","text":"In contrast to this pattern,"},{"key":"D","text":"Regardless of these observations,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "On the basis of these findings," because the sentence that follows presents Voss''s proposal, which is built directly upon the observation that bioluminescence coincides with peak spore-dispersal season. "In other words" incorrectly signals a restatement, but Voss''s proposal adds a new explanatory claim rather than rephrasing the prior sentence. "In contrast to this pattern" wrongly signals opposition, when the proposal aligns with the observation. "Regardless of these observations" implies the proposal is unrelated to the findings, which contradicts the logical connection between seasonal bioluminescence and the insect-dispersal hypothesis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KHH3HR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every spring, the conservation team at Barrow Creek Reserve _____ a thorough census of nesting shorebirds along the estuary, cataloging each species and recording clutch sizes.', $lyceon_json$[{"key":"A","text":"conducts"},{"key":"B","text":"conduct"},{"key":"C","text":"have conducted"},{"key":"D","text":"are conducting"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "the conservation team," which is a singular collective noun requiring the singular verb form "conducts." The plural form "conduct" does not agree with the singular subject "team." The form "have conducted" incorrectly shifts to the present perfect tense, conflicting with the habitual present indicated by "Every spring." The form "are conducting" shifts to the present progressive, which implies an action happening right now rather than a recurring seasonal activity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M66PDH', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Cognitive psychologist Darren Whitfield conducted a study in which participants were asked to estimate the caloric content of meals. One group viewed each meal as a single composed plate, while a second group viewed the same meal''s components presented separately on individual dishes. Whitfield found that participants in the separated-components group estimated total caloric content 23% higher than those viewing the composed plate, even though the food items and portions were identical. These results suggest that ________', $lyceon_json$[{"key":"A","text":"the visual presentation format of a meal can significantly influence people's perception of its caloric content, independent of the actual quantity of food being assessed"},{"key":"B","text":"participants in the separated-components group had more prior experience with nutrition labeling and portion-size estimation, which accounts for their higher and more accurate caloric estimates"},{"key":"C","text":"restaurants that serve meals on single composed plates are deliberately attempting to mislead customers into underestimating the number of calories they are consuming during each visit"},{"key":"D","text":"Whitfield's study demonstrates that people are generally incapable of making accurate caloric estimates regardless of how food is presented, since both groups produced estimates that diverged substantially from actual values"}]$lyceon_json$::jsonb, 'A', NULL, E'The study held food quantity constant and varied only presentation format, producing a 23% difference in caloric estimates. The inference that visual presentation format influences caloric perception independent of actual quantity follows directly from this experimental design. The claim about prior nutrition experience introduces an unmentioned variable and assumes, without evidence, that higher estimates were more accurate. The claim about restaurants deliberately misleading customers attributes intent that the text does not address. The claim that people are generally incapable of accurate estimates is unsupported; the text discusses a systematic difference between conditions, not overall inaccuracy, and does not report how either group''s estimates compared to actual caloric values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N1CHVC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to present Kimura''s findings to an audience unfamiliar with urban transit planning while acknowledging a significant limitation of the tram-based approach. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While writing a report on urban noise pollution for an environmental policy course, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NG872B', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Economist Maria Kellner argues that remote work arrangements universally increase employee productivity. She cites a 2021 survey in which 78 percent of remote workers reported completing tasks more efficiently at home than in a traditional office setting.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NPZVFX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice most effectively uses data from the study to support the claim that municipalities with higher percentages of permeable surface area experienced less severe flooding during the 2021 storm season?', E'Urban hydrologist Jian-Wei Chen analyzed flooding outcomes across five municipalities in the Willamette Valley during the 2021 storm season. Chen argues that municipalities with greater permeable surface area (parks, unpaved lots, rain gardens) absorbed more stormwater, reducing flood severity. Chen''s data showed the following results for each municipality''s permeable surface percentage and the average depth of street flooding recorded during the three heaviest storms: Brooksfield had 38% permeable surface and 4.2 cm average flood depth; Dunmore had 17% and 14.7 cm; Elswick had 29% and 8.1 cm; Harston had 11% and 19.3 cm; Pellham had 44% and 2.9 cm.', $lyceon_json$[{"key":"A","text":"Brooksfield and Pellham together account for the largest total area of permeable surfaces among all five municipalities studied by Chen"},{"key":"B","text":"Pellham, which had the highest permeable surface percentage at 44%, recorded the lowest average flood depth at 2.9 cm, while Harston, with only 11% permeable surface, recorded the highest flood depth at 19.3 cm"},{"key":"C","text":"Dunmore's average flood depth of 14.7 cm was recorded during the three heaviest storms of the season rather than across all precipitation events that occurred in 2021"},{"key":"D","text":"The five municipalities in the Willamette Valley experienced a total of twelve significant storm events during the 2021 season, three of which produced the flooding data presented in Chen's study, as described in the passage."}]$lyceon_json$::jsonb, 'B', NULL, E'The claim is that higher permeable surface correlates with less severe flooding. Comparing the municipality with the highest permeable percentage (Pellham, 44%, flood depth 2.9 cm) to the one with the lowest (Harston, 11%, flood depth 19.3 cm) directly illustrates this inverse relationship using specific data points. The claim about total area of permeable surfaces is not supported by the table, which shows percentages, not total areas. The observation about Dunmore''s flood depth being measured during the three heaviest storms merely restates the study''s methodology without connecting permeability to flooding outcomes. The claim about twelve storm events introduces information not present in the passage or table.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NW9EJM', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the novelist Emeka Osei had envisioned a trilogy spanning three centuries of West African trade routes, his publisher urged him to condense the narrative. By the time the final manuscript reached the editorial _____ seventeen times to tighten the chronological scope.', $lyceon_json$[{"key":"A","text":"board, Osei had revised the opening chapter"},{"key":"B","text":"board, Osei has revised the opening chapter"},{"key":"C","text":"board; Osei would have revised the opening chapter"},{"key":"D","text":"board, Osei was revising the opening chapter"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction "By the time the final manuscript reached the editorial board" establishes a past reference point, and the action of revising was completed before that point. The past perfect "had revised" correctly signals an action completed prior to another past event. The present perfect "has revised" is incorrect because the entire narrative is set in the past, so a present-tense anchor does not fit. The conditional "would have revised" implies a hypothetical scenario that did not occur, which contradicts the factual tone of the passage. The past progressive "was revising" indicates an action in progress at the moment the manuscript reached the board, but the sentence specifies the total count of revisions (seventeen times), indicating a completed action rather than one still underway.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OL5RMC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to connect Delgado''s Antarctic findings to the broader search for extraterrestrial life while highlighting a specific constraint on microbial survival that her research identified. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While drafting an article about Antarctic microbiology for a popular science magazine, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OMQ8L3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 2019, marine biologist Anika Prasad documented an unusual feeding behavior among spinner dolphins off the coast of Mozambique. Rather than hunting individually or in small groups, as is typical of spinner dolphins in other regions, the Mozambican population coordinated in spiraling formations of up to forty individuals to drive schools of lanternfish toward the surface. Prasad noted that these formations were remarkably consistent across observations, suggesting that the behavior is learned and transmitted within the population rather than arising spontaneously.', $lyceon_json$[{"key":"A","text":"Spinner dolphins in Mozambique have developed a distinctive, coordinated hunting strategy that appears to be culturally transmitted"},{"key":"B","text":"Lanternfish are the primary prey species for spinner dolphins across all regions of the Indian Ocean"},{"key":"C","text":"Marine biologists have recently begun studying the social behaviors of spinner dolphins in the waters near Mozambique"},{"key":"D","text":"Anika Prasad's 2019 research demonstrated that spinner dolphins are more intelligent than scientists had previously believed them to be"}]$lyceon_json$::jsonb, 'A', NULL, E'The text describes a specific coordinated hunting behavior among Mozambican spinner dolphins and notes that it appears to be learned and transmitted within the population. The choice stating that these dolphins have developed a distinctive, coordinated hunting strategy that appears culturally transmitted captures this main idea. The claim about lanternfish being the primary prey across all Indian Ocean regions misreads a detail; the text only discusses one location. The claim about marine biologists recently beginning to study social behaviors is too vague and misses the specific finding. The claim about demonstrating dolphins are more intelligent than previously believed oversteps what the text states; cultural transmission of behavior is not equated with a broader intelligence claim.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R6BB64', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Paleobotanist Luciana Ferreira analyzed fossilized pollen deposits from a series of lake sediment cores in central Patagonia, spanning a period from roughly 11,000 to 8,500 years ago. During this interval, southern beech (Nothofagus) pollen concentrations declined sharply while grass and composite herb pollen increased. Ferreira notes that this vegetational shift coincided with a well-documented period of decreased precipitation in the region. However, charcoal fragment concentrations in the same sediment layers also increased dramatically during this period, and Ferreira has found that the charcoal increase preceded the pollen shift by approximately 200 years in the stratigraphic record. On the basis of these observations, Ferreira concludes that ________', $lyceon_json$[{"key":"A","text":"the replacement of southern beech forests by grasslands was driven primarily by decreased precipitation, with fire playing at most a minor secondary role in the vegetational transition across central Patagonia"},{"key":"B","text":"fire disturbance likely initiated the decline of southern beech forests before decreased precipitation alone would have caused a comparable shift, though drier conditions may have subsequently reinforced the transition to grassland vegetation"},{"key":"C","text":"the charcoal fragments found in the sediment cores originated from volcanic eruptions rather than from grassland or forest fires, meaning that fire was not a factor in the observed vegetational changes during this period"},{"key":"D","text":"southern beech forests throughout all of South America experienced a uniform decline between 11,000 and 8,500 years ago as a result of continental-scale climate changes that simultaneously affected precipitation, temperature, and fire frequency"}]$lyceon_json$::jsonb, 'B', NULL, E'The key evidence is the 200-year lead of charcoal increase over the pollen shift: fire preceded the vegetational change, while decreased precipitation coincided with it. The inference that fire likely initiated the forest decline before precipitation alone would have caused it, with drier conditions reinforcing the transition, accounts for both the temporal sequence and the concurrent drying. The claim that decreased precipitation was the primary driver with fire playing a minor role contradicts the stratigraphic evidence showing charcoal increasing first. The claim that charcoal originated from volcanic eruptions rather than fires introduces an alternative explanation the text does not support and contradicts Ferreira''s own interpretive framing. The claim about a uniform decline across all of South America extrapolates far beyond the study''s central Patagonian scope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RSFW6J', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to emphasize the continued commitment of Zapotec weavers to traditional dyeing methods despite the availability of modern alternatives. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While writing about the textile traditions of the Zapotec communities in Oaxaca, Mexico, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VMRJCS', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which choice best supports the researcher''s claim about the function of pigmentation changes in Arctic hares?', E'Wildlife biologist Renata Okonkwo has studied seasonal pigmentation changes in Arctic hare populations across northern Ellesmere Island. She claims that the shift from brown summer fur to white winter fur serves primarily as camouflage against predators rather than as thermoregulation. To test this, she compared predation rates on hares whose molt timing matched the snowfall schedule with predation rates on hares whose molt was delayed by unusually late snow.', $lyceon_json$[{"key":"A","text":"Hares with delayed molts that remained brown against white snow experienced predation rates three times higher than hares whose white fur matched the snow cover"},{"key":"B","text":"Arctic hares on Ellesmere Island consume a diet consisting primarily of woody shrubs and mosses during the winter months when other vegetation is buried beneath snow"},{"key":"C","text":"The white winter fur of Arctic hares contains hollow hair shafts that trap air and provide substantial insulating capacity against extreme cold temperatures experienced in the high Arctic"},{"key":"D","text":"Arctic hare populations on Ellesmere Island have remained relatively stable over the past two decades despite significant fluctuations in average winter temperatures across the region"}]$lyceon_json$::jsonb, 'A', NULL, E'Okonkwo claims the pigmentation change is primarily for camouflage, not thermoregulation. The finding that mismatched hares (brown against white snow) suffered far higher predation directly supports a camouflage function. The detail about diet composition is irrelevant to whether fur color serves as camouflage or thermoregulation. The detail about hollow hair shafts providing insulation would actually support the thermoregulation hypothesis, undermining the researcher''s claim. The detail about stable populations despite temperature fluctuations does not address the mechanism of pigmentation changes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W3J0BL', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Ecologist Tomasz Wierzbicki has proposed that the high species diversity observed in certain volcanic archipelagos cannot be adequately explained by the traditional island biogeography model, which emphasizes island size and distance from the mainland as primary predictors of species richness. Wierzbicki points to the Marquesan beetle fauna: despite the archipelago''s extreme remoteness and relatively small total land area, it hosts over 370 endemic beetle species. He attributes this to the islands'' dramatic elevational gradients, which create numerous distinct microclimates within short horizontal distances. Each microclimate, Wierzbicki argues, functions as a semi-isolated habitat that promotes independent speciation events. However, Wierzbicki acknowledges that elevational gradients alone do not fully account for the pattern, since comparably steep islands in other ocean basins do not exhibit similar levels of endemism. He suggests that the Marquesas'' particular geological history, including repeated cycles of volcanic eruption and erosion, has created an unusually dynamic landscape that both fragments and reconnects habitats over evolutionary timescales.', $lyceon_json$[{"key":"A","text":"Wierzbicki argues that traditional island biogeography is fundamentally flawed and should be replaced with a model based entirely on elevational gradients and microclimate diversity"},{"key":"B","text":"The Marquesan beetle fauna's diversity is primarily the result of the archipelago's proximity to continental species pools, which traditional biogeography models have underestimated in their analyses"},{"key":"C","text":"Wierzbicki proposes that the exceptional diversity in certain volcanic archipelagos results from a combination of elevational microclimates and dynamic geological processes that traditional models do not fully capture"},{"key":"D","text":"Volcanic archipelagos consistently exhibit higher species diversity than continental islands because repeated eruption cycles create habitat fragmentation that drives speciation at rates unmatched elsewhere in comparable ecosystems"}]$lyceon_json$::jsonb, 'C', NULL, E'The text describes Wierzbicki''s argument in two stages: elevational gradients create microclimates that promote speciation, but since comparable gradients elsewhere do not produce the same result, geological dynamism also plays a role. The choice identifying the combination of elevational microclimates and dynamic geological processes as exceeding what traditional models capture accurately summarizes this layered argument. The claim that traditional biogeography is fundamentally flawed and should be entirely replaced overstates Wierzbicki''s position; he says the model is inadequate for these cases, not that it should be discarded wholesale. The claim about proximity to continental species pools directly contradicts the text, which emphasizes the Marquesas'' extreme remoteness. The claim that volcanic archipelagos consistently exhibit higher diversity universalizes a pattern the text attributes to specific conditions, not to all volcanic islands.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XDI6J4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which choice best describes data from the study that would weaken the researchers'' conclusion?', E'Nutritional scientists at the University of Coimbra conducted a seven-month study examining whether supplementation with fermented barley extract improved iron absorption in adults with mild iron deficiency. Participants were divided into two groups: one received a daily capsule containing 400 mg of fermented barley extract, and the other received a placebo. At the study''s conclusion, the researchers found that the supplementation group''s mean serum ferritin levels had increased by 18% compared to a 3% increase in the placebo group. The researchers concluded that fermented barley extract meaningfully enhances iron absorption in iron-deficient adults.', $lyceon_json$[{"key":"A","text":"Participants in the supplementation group reported no significant gastrointestinal side effects during the seven-month trial period compared to the placebo group"},{"key":"B","text":"A follow-up analysis revealed that 71% of the ferritin increase in the supplementation group occurred among participants who had independently changed their diets to include more iron-rich foods during the study period"},{"key":"C","text":"The fermented barley extract used in the study was produced by a process that preserves the bioavailability of naturally occurring B vitamins in addition to its effects on mineral absorption"},{"key":"D","text":"Previous studies on non-fermented barley extract have shown no significant effect on iron absorption, suggesting that the fermentation process itself is a necessary component of the extract's observed efficacy in this particular trial"}]$lyceon_json$::jsonb, 'B', NULL, E'The researchers concluded that the barley extract enhanced iron absorption. The finding that most of the ferritin increase came from participants who independently changed their diets introduces a confounding variable, suggesting the improvement may be attributable to dietary changes rather than the supplement itself. This directly weakens the causal conclusion. The absence of gastrointestinal side effects concerns tolerability, not the validity of the absorption claim. The preservation of B vitamins is irrelevant to whether the extract improves iron absorption specifically. The finding that non-fermented extract showed no effect actually strengthens the conclusion by suggesting fermentation is the active component, rather than weakening it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XQT6BD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Claudette Rennard has challenged the prevailing interpretation of the 1843 Bordeaux textile workers'' strike. Earlier scholars characterized the strike as primarily an economic protest against wage reductions. Rennard, however, drawing on previously unexamined correspondence between strike organizers, argues that the workers'' central grievance was the introduction of a monitoring system that required them to log their movements within the factory. While wage concerns were certainly present, Rennard contends that the correspondence reveals these were secondary to the workers'' objection to what they perceived as an erosion of their autonomy on the factory floor.', $lyceon_json$[{"key":"A","text":"The 1843 Bordeaux strike was ultimately unsuccessful in achieving the workers' demands regarding either wages or factory monitoring practices"},{"key":"B","text":"Rennard's research into organizer correspondence suggests the 1843 Bordeaux strike was driven more by concerns about worker autonomy than by wage disputes, contrary to earlier scholarly views"},{"key":"C","text":"Earlier scholars who studied the 1843 Bordeaux strike failed to consult any primary source documents from the period and therefore reached inaccurate conclusions about the strike's causes"},{"key":"D","text":"Rennard has uncovered evidence that wage reductions in Bordeaux textile factories during the 1840s were far more severe than historians had previously recognized or documented in their analyses"}]$lyceon_json$::jsonb, 'B', NULL, E'The text presents Rennard''s challenge to the prevailing interpretation: the strike was primarily about autonomy (the monitoring system), not wages. The choice identifying Rennard''s correspondence-based argument as reframing the strike around autonomy rather than wages captures the central idea. The claim about the strike being unsuccessful introduces an outcome the text never discusses. The claim that earlier scholars failed to consult any primary sources overstates the text, which says Rennard used ''previously unexamined'' correspondence, not that earlier scholars used no primary sources at all. The claim about wage reductions being more severe than recognized contradicts the text, which argues wages were secondary, not underestimated.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-11"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-11","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
